#include "DiscreteElasticRod.cpp"
#include <iomanip>
#include <iostream>
#include <stdexcept>
using namespace metalrobo;
constexpr double L=.025,E=2.129e9,I=3.960e-12,area=3.449e-6,radius=.00185,density=1200,delta=.000025,dh=.00000001;
DiscreteElasticRodModel model(unsigned n){DiscreteRodMaterial mat{.radius=radius,.density=density,.youngModulus=E,.poissonRatio=.35};auto m=makeStraightSutureRod(n,L,mat);m.name="related_crow_rachis_energy_instrument";m.fidelityBoundary="uniform short-segment surrogate; carrion crow sample";std::fill(m.bendStiffness.begin(),m.bendStiffness.end(),E*I);std::fill(m.stretchStiffness.begin(),m.stretchStiffness.end(),E*area);double dm=density*area*L/(n-1);for(unsigned j=0;j<n;++j)m.nodeMasses[j]=(j==0||j==n-1)?.5*dm:dm;return m;}
DiscreteElasticRodState shaped(const DiscreteElasticRodModel&m,double d){auto s=makeDiscreteElasticRodDefaultState(m);for(auto& p:s.positions){double x=p[0]/L;if(x>.5)x=1-x;p[1]=d*(3*x-4*x*x*x);}return s;}
double energy(const DiscreteElasticRodModel&m,double d){auto s=shaped(m,d);DiscreteElasticRodEnergy e;auto diag=evaluateDiscreteElasticRodEnergy(m,s,e);if(!diag.succeeded())throw std::runtime_error("energy reference failed");return e.total();}
namespace metalrobo { double localBendEnergy(const DiscreteElasticRodModel&m,const DiscreteElasticRodState&s){RodReferenceFrames refs;RodFrames rest;if(!buildReferenceFrames(m.restPositions,refs)||!buildFrames(m.restPositions,m.restTwists,refs,rest))throw std::runtime_error("rest frame failed");double total=0;for(size_t v=0;v<m.bendStiffness.size();++v){std::array<Vec3,3> p{{s.positions[v],s.positions[v+1],s.positions[v+2]}};std::array<double,2> tw{{s.twists[v],s.twists[v+1]}};std::array<Vec3,2> t{{refs.tangents[v],refs.tangents[v+1]}},di{{refs.directors[v],refs.directors[v+1]}};std::array<double,2> c{};if(!localCurvature(p,tw,t,di,c))throw std::runtime_error("local curvature failed");double length=.5*(m.restLengths[v]+m.restLengths[v+1]);double c0=c[0]-rest.curvature[v][0],c1=c[1]-rest.curvature[v][1];total+=.5*m.bendStiffness[v]/length*(c0*c0+c1*c1);}return total;} }
double globalBend(const DiscreteElasticRodModel&m,const DiscreteElasticRodState&s){DiscreteElasticRodEnergy e;if(!evaluateDiscreteElasticRodEnergy(m,s,e).succeeded())throw std::runtime_error("global energy failed");return e.bend;}
int main(){try{std::cout<<std::setprecision(14);auto m=model(9);for(int f=-1;f<3;++f){auto s=shaped(m,delta);if(f>=0){for(auto&p:s.positions)for(auto&z:p)if(!(std::cin>>z))throw std::runtime_error("positions missing");for(auto&v:s.velocities)for(auto&z:v)if(!(std::cin>>z))throw std::runtime_error("velocities missing");}std::cout<<"{\"frame\":"<<f<<",\"global\":"<<globalBend(m,s)<<",\"local\":"<<metalrobo::localBendEnergy(m,s)<<",\"global_derivative\":[";for(int mode=0;mode<2;++mode){if(mode)std::cout<<"],\"local_derivative\":[";for(int i=0;i<9;++i){double h=1e-9;s.positions[i][1]+=h;double ep=mode?metalrobo::localBendEnergy(m,s):globalBend(m,s);s.positions[i][1]-=2*h;double em=mode?metalrobo::localBendEnergy(m,s):globalBend(m,s);s.positions[i][1]+=h;if(i)std::cout<<',';std::cout<<(ep-em)/(2*h);}}std::cout<<"]}\n";}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}